var FX_POOL = ['wa', 'jump', 'spin', 'grow', 'multiply', 'confetti', 'tint', 'sky', 'tilt', 'float', 'friend', 'rain', 'fov', 'grav', 'speed', 'babble', 'bigwa', 'shrink', 'time', 'fog'];
