    o.traverse && pr.def.b === 'barber' && o.children.forEach(function (c) { if (c.name === 'spin') c.rotation.y += dt * 3; });
    if (pr.def.b === 'garapon' && pr.spin > 0) o.children.forEach(function (c) { if (c.name === 'spin2') c.rotation.y += dt * 10; });
