  if (z < -37 && x > -55) return 'eki';
  if (x < -37 && z > -62 && z < 40) return 'danchi';
  if (x > 25 && x < 75 && z > -37 && z < 27) return 'shoten';
  if (Math.abs(x) < 27 && Math.abs(z) < 27) return 'koen';
